-- Property submissions from the public "list your property" form, their
-- photos, and the app_settings table behind the admin Settings page.
CREATE TYPE "public"."submission_status" AS ENUM('incomplete', 'pending', 'approved', 'rejected', 'spam');--> statement-breakpoint
CREATE TYPE "public"."submitter_role" AS ENUM('owner', 'co_owner', 'representative');--> statement-breakpoint
CREATE TABLE "property_submissions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"reference" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "property_submissions_reference_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1000 CACHE 1),
	"status" "submission_status" DEFAULT 'incomplete' NOT NULL,
	"deal_type" "deal_type",
	"property_kind" "property_kind",
	"location_id" uuid,
	"location_text" text,
	"address" text,
	"price" numeric(12, 2),
	"currency" "currency" DEFAULT 'EUR' NOT NULL,
	"area" numeric(10, 2),
	"land_area" numeric(12, 2),
	"rooms" integer,
	"bedrooms" integer,
	"bathrooms" integer,
	"floor" integer,
	"floors_total" integer,
	"year_built" integer,
	"construction_type" "construction_type",
	"heating" "heating_type",
	"furnishing" "furnishing",
	"condition" "listing_condition",
	"feature_keys" text[] DEFAULT '{}'::text[] NOT NULL,
	"maintenance_fee" numeric(10, 2),
	"deposit_months" integer,
	"available_from" date,
	"description" text DEFAULT '' NOT NULL,
	"external_media_url" text,
	"locale" "locale" DEFAULT 'bg' NOT NULL,
	"first_name" text,
	"last_name" text,
	"email" text,
	"phone" text,
	"submitter_role" "submitter_role",
	"contact_time" text,
	"consent_at" timestamp with time zone,
	"ip_hash" text,
	"user_agent" text,
	"reviewed_by" text,
	"reviewed_at" timestamp with time zone,
	"rejection_reason" text,
	"internal_note" text,
	"listing_id" uuid,
	"submitted_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "submission_photos" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"submission_id" uuid NOT NULL,
	"storage_key" text NOT NULL,
	"thumb_key" text NOT NULL,
	"width" integer NOT NULL,
	"height" integer NOT NULL,
	"bytes" integer NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"imported_media_id" uuid,
	"purged_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "app_settings" (
	"key" text PRIMARY KEY NOT NULL,
	"value" jsonb NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" text
);
--> statement-breakpoint
